package tri_lion.health.domain.routine;import jakarta.persistence.*;import java.time.LocalDate;import lombok.*;
@Entity@Table(name="routine_days")@Getter@NoArgsConstructor(access=AccessLevel.PROTECTED)public class RoutineDay{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)@Column(name="routine_day_id")private Long id;@Column(name="personalized_routine_id")private Long routineId;@Column(name="week_number")private int week;@Column(name="day_of_week")private String dayOfWeek;@Column(name="scheduled_date")private LocalDate scheduledDate;@Column(name="estimated_minutes")private Integer estimatedMinutes;public RoutineDay(Long r,int w,LocalDate d,int mins){routineId=r;week=w;scheduledDate=d;dayOfWeek=d.getDayOfWeek().name();estimatedMinutes=mins;}}
